// Настройки поиска и окно выборки.
const QUERIES = [
  { text: 'python', region: '7700000000' },
  { text: 'javascript', region: '7700000000' },
  { text: 'frontend', region: '7800000000' },
];
const MAX_AGE_DAYS = 3;

const staticData = $getWorkflowStaticData('global');
const lastRunAt = staticData.lastRunAt ?? null;

// С прошлого запуска минус нахлёст 6 ч: вакансии попадают в API с задержкой.
const fallback = Date.now() - MAX_AGE_DAYS * 86400000;
const previous = lastRunAt ? Date.parse(lastRunAt) : NaN;
const from = Number.isNaN(previous) ? fallback : previous - 6 * 3600000;
const modifiedFrom = new Date(from).toISOString().replace(/\.\d{3}Z$/, 'Z');

return QUERIES.map((query) => {
  const base = 'https://opendata.trudvsem.ru/api/v1/vacancies'
    + (query.region ? '/region/' + query.region : '');
  const params = new URLSearchParams({ limit: '100', offset: '0', text: query.text, modifiedFrom });
  return { json: { url: base + '?' + params.toString(), query: query.text, modifiedFrom } };
});

// Нормализация, фильтры и дедупликация — та же логика, что в src/filter.js.
const MIN_SALARY = 80000;
const REQUIRE_SALARY = false;
const MAX_AGE_DAYS = 3;
const MAX_PER_RUN = 12;
const EXCLUDE = ['вахта', 'курьер', 'продавец', 'оператор call', 'менеджер по продажам'];

const staticData = $getWorkflowStaticData('global');
const sentIds = new Set(staticData.sentIds ?? []);

function normalize(raw) {
  const v = raw.vacancy ?? raw;
  let requirement = v.requirement;
  if (typeof requirement === 'string') {
    try { requirement = JSON.parse(requirement); } catch { requirement = {}; }
  }
  return {
    id: v.id,
    title: v['job-name'] ?? '',
    company: v.company?.name ?? 'не указана',
    region: v.region?.name ?? '',
    url: v.vac_url ?? '',
    salaryMin: Number(v.salary_min) || 0,
    salaryMax: Number(v.salary_max) || 0,
    schedule: v.schedule ?? '',
    experienceYears: Number(requirement?.experience) || 0,
    description: v.duty ?? '',
    createdAt: v['creation-date'] ?? '',
    modifiedAt: v.date_modify ?? '',
  };
}

const collected = [];
for (const item of $input.all()) {
  for (const raw of item.json?.results?.vacancies ?? []) collected.push(normalize(raw));
}

function daysSince(dateString) {
  const parsed = Date.parse(dateString ?? '');
  return Number.isNaN(parsed) ? Infinity : (Date.now() - parsed) / 86400000;
}

const unique = new Map();
for (const vacancy of collected) {
  if (!vacancy.id || sentIds.has(vacancy.id) || unique.has(vacancy.id)) continue;

  const salary = Math.max(vacancy.salaryMax, vacancy.salaryMin);
  if (REQUIRE_SALARY && salary === 0) continue;
  if (salary > 0 && salary < MIN_SALARY) continue;
  if (daysSince(vacancy.modifiedAt || vacancy.createdAt) > MAX_AGE_DAYS) continue;

  const haystack = (vacancy.title + ' ' + vacancy.description).toLowerCase();
  if (EXCLUDE.some((word) => haystack.includes(word))) continue;

  unique.set(vacancy.id, vacancy);
}

const fresh = [...unique.values()]
  .sort((a, b) => Date.parse(b.modifiedAt || b.createdAt || 0) - Date.parse(a.modifiedAt || a.createdAt || 0))
  .slice(0, MAX_PER_RUN);

// Окно двигаем всегда, отправленные id — только при наличии новых.
staticData.lastRunAt = new Date().toISOString();
if (fresh.length) {
  staticData.sentIds = [...(staticData.sentIds ?? []), ...fresh.map((v) => v.id)].slice(-3000);
}

if (fresh.length === 0) return [];

function escapeHtml(text) {
  return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function formatSalary(v) {
  if (!v.salaryMin && !v.salaryMax) return 'не указана';
  const money = (n) => n.toLocaleString('ru-RU') + ' ₽';
  if (v.salaryMin && v.salaryMax && v.salaryMin !== v.salaryMax) {
    return money(v.salaryMin) + ' – ' + money(v.salaryMax);
  }
  return v.salaryMin ? 'от ' + money(v.salaryMin) : 'до ' + money(v.salaryMax);
}

const blocks = fresh.map((v, i) => {
  const lines = [
    '<b>' + (i + 1) + '. ' + escapeHtml(v.title) + '</b>',
    '🏢 ' + escapeHtml(v.company),
    '💰 ' + escapeHtml(formatSalary(v)),
  ];
  if (v.region) lines.push('📍 ' + escapeHtml(v.region));
  if (v.experienceYears) lines.push('🎓 опыт от ' + v.experienceYears + ' лет');
  if (v.schedule) lines.push('🕒 ' + escapeHtml(v.schedule));
  if (v.url) lines.push('<a href="' + escapeHtml(v.url) + '">Открыть вакансию</a>');
  return lines.join('\n');
});

// Режем дайджест по лимиту Telegram в 4096 символов.
const messages = [];
let current = '🎯 <b>Новые вакансии: ' + fresh.length + '</b>';
for (const block of blocks) {
  const candidate = current + '\n\n' + block;
  if (candidate.length > 4096) { messages.push(current); current = block; } else { current = candidate; }
}
messages.push(current);

return messages.map((text) => ({ json: { text } }));
